  "inlineSchema": "// prisma/schema.prisma\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Papel {\n  admin\n  guiche\n  acertador\n  dgp\n  financeiro\n}\n\nenum Frota {\n  buzin\n  lbm\n  meli\n}\n\nenum StatusMotorista {\n  ativo\n  desligado\n}\n\nenum CategoriaMotorista {\n  frota\n  dedicado_usiminas\n  dedicado_arcelormittal\n  patio\n  tirador_ferias\n}\n\nenum StatusSolicitacao {\n  pendente\n  pago\n}\n\nmodel Usuario {\n  id                String   @id @default(uuid())\n  nome              String\n  email             String   @unique\n  senha             String\n  papel             Papel\n  ativo             Boolean  @default(true)\n  permissoes        Json?\n  criadoEm          DateTime @default(now())\n  perfilAgendamento Int?\n\n  solicitacoes     Solicitacao[]\n  exclusoes        ExclusaoVale[]\n  auditoriasFeitas Auditoria[]\n\n  @@map(\"usuarios\")\n}\n\nmodel Motorista {\n  id           String             @id @default(uuid())\n  nome         String\n  cpf          String             @unique\n  contato      String\n  banco        String?\n  agencia      String?\n  conta        String?\n  pix          String?\n  destinatario String?\n  frota        Frota\n  status       StatusMotorista    @default(ativo)\n  categoria    CategoriaMotorista\n  criadoEm     DateTime           @default(now())\n  atualizadoEm DateTime           @updatedAt\n  excluido     Boolean            @default(false)\n\n  solicitacoes       Solicitacao[]\n  exclusoes          ExclusaoVale[]\n  folgas             Folga[]\n  ferias             Ferias[]\n  agendamentos       Agendamento[]\n  controleFinanceiro ControleFinanceiro[]\n  auditorias         Auditoria[]\n  afastamentos       Afastamento[]\n  abandonos          Abandono[]\n\n  @@map(\"motoristas\")\n}\n\nmodel TipoSolicitacao {\n  id           String        @id @default(uuid())\n  nome         String        @unique\n  ativo        Boolean       @default(true)\n  solicitacoes Solicitacao[]\n\n  @@map(\"tipos_solicitacao\")\n}\n\nmodel Solicitacao {\n  id            String            @id @default(uuid())\n  solicitante   Usuario           @relation(fields: [solicitanteId], references: [id])\n  solicitanteId String\n  data          DateTime\n  tipo          TipoSolicitacao   @relation(fields: [tipoId], references: [id])\n  tipoId        String\n  motorista     Motorista         @relation(fields: [motoristaId], references: [id])\n  motoristaId   String\n  placa         String?\n  valor         Decimal           @db.Decimal(10, 2)\n  liberado      Decimal?          @db.Decimal(10, 2)\n  status        StatusSolicitacao @default(pendente)\n  anexoUrl      String?\n  criadoEm      DateTime          @default(now())\n  atualizadoEm  DateTime          @updatedAt\n\n  auditorias Auditoria[]\n\n  @@map(\"solicitacoes\")\n}\n\nmodel ExclusaoVale {\n  id            String    @id @default(uuid())\n  solicitante   Usuario   @relation(fields: [solicitanteId], references: [id])\n  solicitanteId String\n  numeroVale    String\n  dataVale      DateTime\n  motorista     Motorista @relation(fields: [motoristaId], references: [id])\n  motoristaId   String\n  motivo        String\n  feito         Boolean   @default(false)\n  criadoEm      DateTime  @default(now())\n  atualizadoEm  DateTime  @updatedAt\n\n  auditorias Auditoria[]\n\n  @@map(\"exclusoes_vale\")\n}\n\nmodel Folga {\n  id             String    @id @default(uuid())\n  motorista      Motorista @relation(fields: [motoristaId], references: [id])\n  motoristaId    String\n  periodo        DateTime\n  quantidadeDias Int\n  valorTotal     Decimal   @db.Decimal(10, 2)\n  enviado        Boolean   @default(false)\n  criadoEm       DateTime  @default(now())\n  atualizadoEm   DateTime  @updatedAt\n\n  auditorias Auditoria[]\n\n  @@map(\"folgas\")\n}\n\nmodel Ferias {\n  id             String    @id @default(uuid())\n  motorista      Motorista @relation(fields: [motoristaId], references: [id])\n  motoristaId    String\n  tipo           String    @default(\"ferias\") // ferias, atestado\n  inicio         DateTime\n  fim            DateTime?\n  quantidadeDias Int?\n  observacao     String?\n  criadoEm       DateTime  @default(now())\n  atualizadoEm   DateTime  @updatedAt\n\n  auditorias Auditoria[] @relation(\"FeriasAuditoria\")\n\n  @@map(\"ferias\")\n}\n\nmodel Afastamento {\n  id            String    @id @default(uuid())\n  motorista     Motorista @relation(fields: [motoristaId], references: [id])\n  motoristaId   String\n  dataInicio    DateTime\n  dataRetorno   DateTime?\n  indeterminado Boolean   @default(false)\n  retornou      Boolean   @default(false)\n  observacao    String?\n  criadoEm      DateTime  @default(now())\n  atualizadoEm  DateTime  @updatedAt\n\n  @@map(\"afastamentos\")\n}\n\nmodel Abandono {\n  id           String    @id @default(uuid())\n  motorista    Motorista @relation(fields: [motoristaId], references: [id])\n  motoristaId  String\n  data         DateTime\n  observacao   String?\n  criadoEm     DateTime  @default(now())\n  atualizadoEm DateTime  @updatedAt\n\n  @@map(\"abandonos\")\n}\n\nmodel Agendamento {\n  id                String    @id @default(uuid())\n  perfil            Int // 1 ou 2\n  motorista         Motorista @relation(fields: [motoristaId], references: [id])\n  motoristaId       String\n  mesesAcerto       Int\n  mesesSelecionados String[]  @default([])\n  dataHora          DateTime\n  criadoEm          DateTime  @default(now())\n  atualizadoEm      DateTime  @updatedAt\n\n  auditorias Auditoria[]\n\n  @@map(\"agendamentos\")\n}\n\nmodel TipoDesconto {\n  id                 String               @id @default(uuid())\n  nome               String               @unique\n  ativo              Boolean              @default(true)\n  controleFinanceiro ControleFinanceiro[]\n\n  @@map(\"tipos_desconto\")\n}\n\nmodel ControleFinanceiro {\n  id              String       @id @default(uuid())\n  motorista       Motorista    @relation(fields: [motoristaId], references: [id])\n  motoristaId     String\n  tipoDesconto    TipoDesconto @relation(fields: [tipoDescontoId], references: [id])\n  tipoDescontoId  String\n  valor           Decimal      @db.Decimal(10, 2)\n  valorDescontado Decimal      @db.Decimal(10, 2)\n  numeroAcerto    String\n  mesDesconto     String // formato: \"2026-05\"\n  observacao      String?\n  criadoEm        DateTime     @default(now())\n  atualizadoEm    DateTime     @updatedAt\n\n  auditorias Auditoria[]\n\n  @@map(\"controle_financeiro\")\n}\n\nmodel Auditoria {\n  id         String  @id @default(uuid())\n  usuario    Usuario @relation(fields: [usuarioId], references: [id])\n  usuarioId  String\n  acao       String // \"criou\", \"editou\", \"excluiu\"\n  tabela     String\n  registroId String\n\n  motorista     Motorista?          @relation(fields: [motoristaId], references: [id])\n  motoristaId   String?\n  solicitacao   Solicitacao?        @relation(fields: [solicitacaoId], references: [id])\n  solicitacaoId String?\n  exclusao      ExclusaoVale?       @relation(fields: [exclusaoId], references: [id])\n  exclusaoId    String?\n  folga         Folga?              @relation(fields: [folgaId], references: [id])\n  folgaId       String?\n  ferias        Ferias?             @relation(\"FeriasAuditoria\", fields: [feriasId], references: [id])\n  feriasId      String?\n  agendamento   Agendamento?        @relation(fields: [agendamentoId], references: [id])\n  agendamentoId String?\n  controle      ControleFinanceiro? @relation(fields: [controleId], references: [id])\n  controleId    String?\n\n  dadosAntigos Json?\n  dadosNovos   Json?\n  criadoEm     DateTime @default(now())\n\n  @@map(\"auditorias\")\n}\n\nmodel Notificacao {\n  id        String   @id @default(uuid())\n  titulo    String\n  mensagem  String\n  tipo      String // ferias, atestado, afastamento, abandono\n  lida      Boolean  @default(false)\n  usuarioId String? // null = para todos\n  criadoEm  DateTime @default(now())\n\n  @@map(\"notificacoes\")\n}\n",
